// QuestStatusBar — the persistent, TRANSPARENT bottom HUD for quest screens
// (dreamscape, atlas, site views).
//
// It is a TRANSPARENT HUD — no background, no border, no top rule (Principle
// two): the essence total, deck sprite, Dreamcaller bust, and docked dreamsign
// strip sit DIRECTLY on the scene art, made legible by the `.hud-outline` glyph
// dilation (ported into quest-status-bar.css), not by a bar behind them.
// There is no menu-dots button — the menu lives in a top-left menu button on
// the screen.
//
// Everything press-reveals through the one shared engine (Tango's InfoCard /
// reveal coordinator, so timing can't diverge:
//   - the essence value           → InfoCard 'text'
//   - the Dreamcaller bust (pops ABOVE the bar) → InfoCard 'hero'
//   - each docked dreamsign        → InfoCard 'object'
//   - beyond a fixed count, docked dreamsigns collapse into an overflow stack →
//     a centered viewer window (not a bottom sheet)
//
// Pass `stageRef` — the screen root (position:absolute inset:0 in the scaled
// frame); the press-reveal popovers portal into it so placement/clamping use
// stage coordinates.
//
// Ported from the Claude Design "Dreamtides Mobile" project
// (components/quest/QuestStatusBar.jsx / .d.ts). Two deliberate adaptations to
// Tango:
//   - The design source resolves the shared engine + RulesText from a global
//     DS bundle at render time; here it imports Tango's InfoCard engine
//     directly. Dreamsign / Dreamcaller ability text renders as `richText.rules`
//     so glossary keywords highlight in place; UI copy (the essence blurb) uses
//     `richText.plain`.
//   - Each bespoke press target wires `onPointerEnter`/`onPointerLeave` to
//     Tango's input-adaptive reveal source (hover reveals on a fine pointer,
//     press reveals on touch), so the HUD
//     reveals on desktop as well as touch.
//
// The deck sprite — the tentacled card-back with its orange slit eye — is
// embedded as a data URI (150×233, rendered at 63px tall) so there is no
// separate asset to load.

import * as React from "react";
import type { CSSProperties, ReactElement } from "react";
import { richText } from "../card/rich-text";
import { token } from "../../primitives/tokens";
import { type ArtRef, resolveArtRef } from "../../primitives/art";
import { IconButton } from "../controls/IconButton";
import { GlowIcon } from "../controls/GlowIcon";
import { GLYPHS } from "../../primitives/glyph";
import { Dreamsign, dreamsignArtUrl, DS_SHADOW } from "./Dreamsign";
import type { Dreamsign as DreamsignData } from "../../../types/quest";
import { requireDreamsignId } from "../../../data/dreamsigns";
import type { DreamcallerPortraitFocus } from "../../../types/content";
import { DEFAULT_DREAMCALLER_PORTRAIT_FOCUS, dreamcallerRevealSpec } from "./DreamcallerPortrait";
import { useRevealSource } from "../../internal/reveal/context";
import { revealEntityId } from "../../internal/reveal/identity";
import { Pressable } from "../../primitives/Pressable";
import "./quest-status-bar.css";

/** Zooms the dreamcaller bust render so the face fills the circular frame. A
 * bespoke crop factor, named so it reads as an intentional framing crop rather
 * than a magic number in a transform. */
const DREAMCALLER_BUST_CROP_SCALE = 2.9;

/** The docked deck sprite, embedded so there is no separate asset to load. */
const DECK_SPRITE =
  "data:image/png;base64,";

/** How much the `grand` (desktop) HUD scales up from the `compact` (mobile)
 * one. Every HUD measure — the essence type, deck sprite, dreamsign discs, the
 * Dreamcaller bust, and the bar's own height — multiplies by this, so the bar
 * reads identically at desktop widths, just larger. The one factor keeps the
 * whole HUD in proportion. */
const GRAND_SCALE = 1.6;

/** Gap (px) between the docked dreamsign strip and the deck button. A fixed
 * system value, not a caller knob. */
const SIGN_GAP = 8;
/** How many dreamsigns dock inline before the strip collapses into the overflow
 * stack + centered viewer. A fixed system value, not a caller knob. */
const STACK_THRESHOLD = 4;

/** Physical home-indicator inset plus the small scene-art breathing gap. */
export const QUEST_STATUS_BAR_BOTTOM_INSET =
  "calc(var(--safe-area-inset-bottom) + var(--space-2))";

/** Total fixed viewport height occupied by the component. */
export const QUEST_STATUS_BAR_TOTAL_HEIGHT =
  `calc(max(${token("--hud-h")}, var(--qsb-dc-size, 66px)) + ${QUEST_STATUS_BAR_BOTTOM_INSET})`;

/** Operation screens use when reserving content above the fixed component. */
export const QUEST_STATUS_BAR_CLEARANCE_OP =
  "var(--hud-h) + var(--safe-area-inset-bottom) + var(--space-2)";

/** One docked dreamsign, as the domain dreamsign shape the shared
 * {@link Dreamsign} object consumes (art resolved from `imageName`, never by
 * name). The HUD renders each through `<Dreamsign variant="hud">`. */
export type QsbDreamsign = DreamsignData;

/** The active Dreamcaller shown as a bust in the HUD. */
export interface QsbDreamcaller {
  /** Stable Dreamcaller UUID. */
  id: string;
  name: string;
  epithet?: string;
  /** The portrait art as an {@link ArtRef}. Required — a docked Dreamcaller always has art. */
  portrait: ArtRef;
  /** Normalized head position used to center the square HUD crop. */
  portraitFocus?: DreamcallerPortraitFocus;
  ability?: string;
}

export interface QuestStatusBarProps {
  /** Ref to the screen root (position:absolute inset:0 in the scaled frame). Required. */
  stageRef: React.RefObject<HTMLElement | null>;
  /** Essence total shown in the HUD. */
  essence?: number;
  /** The dreamsigns to dock (a small set inline; more collapse to a stack + viewer). */
  dreamsigns?: QsbDreamsign[];
  /** Deck size (used in the deck button's aria-label). */
  deck?: number | string;
  /** Open the deck viewer — fired on a tap / click of the deck sprite. */
  onViewDeck?: () => void;
  dreamcaller?: QsbDreamcaller;
  /** HUD size. `compact` (default) is the mobile / touch size; `grand` is the
   * larger desktop size the dreamscape screen picks above the wide-viewport
   * breakpoint. */
  size?: "compact" | "grand";
}

/* OverflowStack — the overlapping dreamsign stack shown past STACK_THRESHOLD. A
   press compresses it; a tap opens the viewer window. */
function QsbOverflowStack({
  signs,
  onOpenWindow,
}: {
  signs: QsbDreamsign[];
  onOpenWindow: () => void;
}): ReactElement {
  const size = 36;
  return (
    <Pressable
      as="button"
      onClick={onOpenWindow}
      aria-label={`View ${String(signs.length)} dreamsigns`}
      style={{
        display: "flex",
        alignItems: "center",
        padding: 0,
        border: "none",
        background: "none",
        cursor: "pointer",
        touchAction: "none",
        WebkitTapHighlightColor: "transparent",
      }}
    >
      {signs.map((s, i) => (
        <img
          key={requireDreamsignId(s, "QuestStatusBar overflow dreamsign")}
          src={dreamsignArtUrl(String(s.imageName))}
          alt=""
          draggable={false}
          style={{
            width: size,
            height: size,
            objectFit: "contain",
            display: "block",
            marginLeft: i ? -size * 0.46 : 0,
            filter: DS_SHADOW,
            pointerEvents: "none",
          }}
        />
      ))}
    </Pressable>
  );
}

/* HUD strip: positioned just left of the deck button (measured live). */
function QsbDreamsignStrip({
  signs,
  stageRef,
  scale = 1,
  onOpenWindow,
}: {
  signs: QsbDreamsign[];
  stageRef: React.RefObject<HTMLElement | null>;
  scale?: number;
  onOpenWindow: () => void;
}): ReactElement | null {
  const [box, setBox] = React.useState<{
    right: number;
    centerY: number;
  } | null>(null);

  React.useLayoutEffect(() => {
    let raf = 0;
    const measure = (): void => {
      const stage = stageRef.current;
      const deck = stage?.querySelector('button[aria-label^="View deck"]');
      // The dreamsign row shares one line with the essence value — centered on
      // it — so it is placed against the essence element's vertical center
      // rather than the deck's baseline.
      const essence = stage?.querySelector('[aria-label="Essence Total"]');
      const sr = stage?.getBoundingClientRect();
      if (
        !stage ||
        !deck ||
        !essence ||
        !sr ||
        sr.width === 0 ||
        deck.getBoundingClientRect().width === 0
      ) {
        raf = requestAnimationFrame(measure);
        return;
      }
      const dr = deck.getBoundingClientRect();
      const er = essence.getBoundingClientRect();
      const k = stage.clientWidth / sr.width;
      setBox({
        right: stage.clientWidth - (dr.left - sr.left) * k + SIGN_GAP * scale,
        centerY: (er.top + er.height / 2 - sr.top) * k,
      });
    };
    measure();
    const stage = stageRef.current;
    const ro = stage ? new ResizeObserver(measure) : null;
    if (ro && stage) {
      ro.observe(stage);
    }
    window.addEventListener("resize", measure);
    return () => {
      cancelAnimationFrame(raf);
      if (ro) {
        ro.disconnect();
      }
      window.removeEventListener("resize", measure);
    };
  }, [stageRef, signs.length, scale]);

  if (!signs.length || !box) {
    return null;
  }

  const SIGN = Math.round(36 * scale);
  const wrap: CSSProperties = {
    position: "fixed",
    right: box.right,
    top: box.centerY - SIGN / 2,
    display: "flex",
    alignItems: "center",
    zIndex: 41,
    touchAction: "none",
  };

  if (signs.length <= STACK_THRESHOLD) {
    return (
      <div style={{ ...wrap, gap: 2 }}>
        {signs.map((s) => (
          <Dreamsign
            key={requireDreamsignId(s, "QuestStatusBar dreamsign strip")}
            variant="hud"
            dreamsign={s}
            sizePx={SIGN}
          />
        ))}
      </div>
    );
  }

  return (
    <div style={wrap}>
      <QsbOverflowStack signs={signs} onOpenWindow={onOpenWindow} />
    </div>
  );
}

/* the viewer window for the overflow case — a grid of bare dreamsigns. This is
   the one centered solid window (not a bottom sheet). */
function QsbDreamsignWindow({
  signs,
  onClose,
}: {
  signs: QsbDreamsign[];
  onClose: () => void;
}): ReactElement {
  return (
    <div
      onClick={onClose}
      style={{
        position: "absolute",
        inset: 0,
        zIndex: 70,
        display: "grid",
        placeItems: "center",
        padding: token("--gutter"),
        background: token("--scrim"),
        animation: `qsbCardIn ${token("--dur-fast")} ${token("--ease-out")} both`,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          position: "relative",
          width: "min(330px, 100%)",
          padding: "20px 20px 24px",
          background: token("--surface-chrome-strong"),
          border: `1px solid ${token("--border-soft")}`,
          borderRadius: token("--radius-hero"),
          boxShadow: token("--shadow-lg"),
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            marginBottom: 16,
          }}
        >
          <h2
            style={{
              margin: 0,
              font: `600 21px/1 ${token("--font-title")}`,
              color: token("--text-primary"),
            }}
          >
            Dreamsigns
          </h2>
          <IconButton
            glyph={GLYPHS.close}
            size="sm"
            label="Close"
            onPress={onClose}
          />
        </div>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gap: 14,
            justifyItems: "center",
          }}
        >
          {signs.map((s) => (
            <Dreamsign
              key={requireDreamsignId(s, "QuestStatusBar dreamsign window")}
              variant="hud"
              dreamsign={s}
              sizePx={60}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

/* QsbDreamcallerBust — the Dreamcaller portrait button. Owns its own
   press-reveal (like the docked Dreamsign objects): hover reveals on a fine
   pointer, press reveals on touch, and it portals its own 'hero' InfoCard. */
function QsbDreamcallerBust({
  dreamcaller,
}: {
  /** The docked Dreamcaller, or undefined for the empty placeholder frame. */
  dreamcaller?: QsbDreamcaller;
}): ReactElement {
  const binding = useRevealSource({
    identity: { entityType: "dreamcaller", entityId: revealEntityId("dreamcaller", dreamcaller?.id ?? "empty") },
    spec: dreamcaller === undefined
      ? { primary: { kind: "infoCard", card: { variant: "text", title: "Dreamcaller", body: richText.plain("No Dreamcaller is active.") } }, secondaries: [] }
      : dreamcallerRevealSpec({ imageNumber: "", name: dreamcaller.name, title: dreamcaller.epithet ?? "" }, dreamcaller.ability ?? "", dreamcaller.portrait),
  });
  const focus =
    dreamcaller?.portraitFocus ?? DEFAULT_DREAMCALLER_PORTRAIT_FOCUS;
  const focusX = Math.max(0, Math.min(1, focus.x));
  const focusY = Math.max(0, Math.min(1, focus.y));
  const objectPositionY = Math.max(
    0,
    Math.min(1, 3 * focusY - 1 / DREAMCALLER_BUST_CROP_SCALE),
  );
  return (
    <Pressable
      as="button"
      ref={binding.ref}
      {...binding.sourceProps}
      aria-label="Dreamcaller"
      tabIndex={0}
      style={{
        // width/height are fixed by quest-status-bar.css (var(--qsb-dc-size),
        // !important, default 66px); kept here as a same-value fallback for when
        // that stylesheet has not loaded.
        width: 66,
        height: 66,
        flex: "none",
        borderRadius: token("--radius-control"),
        overflow: "hidden",
        border: `2px solid ${token("--border-accent")}`,
        boxShadow: token("--glow-accent-soft"),
        // Faithfully-copied bespoke gradient literal: the first stop #2a2140 has
        // NO exact token equivalent (--primitive-plum-500 is #2a2040, off by one digit),
        // so it stays a literal rather than silently shifting the design color.
        background: `radial-gradient(circle at 50% 30%, #2a2140, ${token("--primitive-void-700")})`,
        padding: 0,
        cursor: "pointer",
        touchAction: "none",
        WebkitTapHighlightColor: "transparent",
        ...binding.sourceProps.style,
      }}
    >
      {dreamcaller && (
        <img
          src={resolveArtRef(dreamcaller.portrait)}
          alt={dreamcaller.name}
          style={{
            position: "relative",
            left: `${String((0.5 - focusX) * 100)}%`,
            width: "100%",
            height: "100%",
            objectFit: "cover",
            objectPosition: `50% ${String(objectPositionY * 100)}%`,
            transform: `scale(${String(DREAMCALLER_BUST_CROP_SCALE)})`,
            transformOrigin: "50% 0%",
          }}
        />
      )}
    </Pressable>
  );
}

/* QsbEssence — the essence total. Owns its own press-reveal (like the docked
   Dreamsign objects) and portals its own 'text' InfoCard, so hover reveals on
   desktop and press reveals on touch. Rendered as the sole <span> child of the
   HUD's column div, matching the DOM shape quest-status-bar.css targets. */
function QsbEssence({
  essence = 0,
  scale = 1,
}: {
  essence?: number;
  scale?: number;
}): ReactElement {
  const binding = useRevealSource({
    identity: { entityType: "resource-essence", entityId: revealEntityId("resource-essence", "quest-total") },
    spec: { primary: { kind: "infoCard", card: { variant: "icon", glyph: GLYPHS.essence, title: "Essence Total", body: richText.plain("A currency you use during quests to modify your deck.") } }, secondaries: [] },
  });
  return (
    <Pressable
      as="span"
      ref={binding.ref}
      {...binding.sourceProps}
      role="button"
      tabIndex={0}
      aria-label="Essence Total"
      style={{
        ...binding.sourceProps.style,
        display: "inline-flex",
        alignItems: "center",
        gap: 0,
        fontFamily: token("--font-ui"),
        fontSize: Math.round(22 * scale),
        fontWeight: 800,
        lineHeight: 1,
        fontVariantNumeric: "tabular-nums",
        color: token("--text-primary"),
        cursor: "pointer",
        touchAction: "none",
        WebkitTapHighlightColor: "transparent",
        transformOrigin: "left center",
      }}
    >
      {essence}
      <GlowIcon
        iconClass={GLYPHS.essence}
        color="essence"
        size={`${String(Math.round(20 * scale))}px`}
      />
    </Pressable>
  );
}

/* QsbHudBar — the bottom HUD row (Dreamcaller bust · essence total · deck
   sprite). The aria-labels + DOM shape match what quest-status-bar.css and the
   press-reveal logic target. */
function QsbHudBar({
  essence = 0,
  deck = 0,
  onViewDeck,
  dreamcaller,
  scale = 1,
}: {
  essence?: number;
  deck?: number | string;
  onViewDeck?: () => void;
  dreamcaller?: QsbDreamcaller;
  scale?: number;
}): ReactElement {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: Math.round(10 * scale),
        height: "100%",
        boxSizing: "border-box",
        paddingTop: 0,
        paddingRight: Math.round(12 * scale),
        paddingBottom: QUEST_STATUS_BAR_BOTTOM_INSET,
        paddingLeft: Math.round(12 * scale),
      }}
    >
      <QsbDreamcallerBust dreamcaller={dreamcaller} />
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 4,
          marginRight: "auto",
        }}
      >
        <QsbEssence essence={essence} scale={scale} />
      </div>
      <button
        type="button"
        className="qsbDeck"
        aria-label={`View deck — ${String(deck)} cards`}
        onClick={onViewDeck}
        style={{
          height: Math.round(66 * scale),
          flex: "none",
          padding: 0,
          border: "none",
          background: "transparent",
          display: "grid",
          placeItems: "center",
          cursor: "pointer",
          WebkitTapHighlightColor: "transparent",
        }}
      >
        <img
          src={DECK_SPRITE}
          alt=""
          draggable={false}
          style={{
            height: Math.round(63 * scale),
            width: "auto",
            display: "block",
            filter:
              "drop-shadow(0 2px 5px rgba(0,0,0,0.6)) drop-shadow(0 0 12px rgba(147,51,234,0.3))",
          }}
        />
      </button>
    </div>
  );
}

/**
 * QuestStatusBar — the persistent, TRANSPARENT bottom HUD for quest screens.
 * Essence total, deck sprite, Dreamcaller bust, and a
 * docked dreamsign strip sit directly on scene art (legible via `.hud-outline`),
 * all press-revealing through the shared InfoCard engine. No menu-dots button.
 */
export function QuestStatusBar({
  stageRef,
  essence,
  dreamsigns = [],
  deck = 0,
  onViewDeck,
  dreamcaller,
  size = "compact",
}: QuestStatusBarProps): ReactElement {
  const [signWindow, setSignWindow] = React.useState(false);
  const scale = size === "grand" ? GRAND_SCALE : 1;
  // The Dreamcaller bust, HUD height, and essence-cluster elevation are sized
  // in quest-status-bar.css from these component vars; scaling them here grows
  // that CSS-driven half of the bar in lockstep with the inline-sized half
  // (essence type, deck sprite, dreamsigns) threaded through as `scale`.
  const rootVars =
    scale === 1
      ? undefined
      : ({
          "--qsb-dc-size": `${String(Math.round(66 * scale))}px`,
          "--hud-h": `${String(Math.round(64 * scale))}px`,
          "--qsb-elev": `${String(Math.round(14 * scale))}px`,
        } as CSSProperties);

  // The essence value and Dreamcaller bust each own their press-reveal
  // (QsbEssence / QsbDreamcallerBust) with per-element onPointerEnter/Leave, so
  // hover reveals on a fine pointer and press reveals on touch. A container-
  // level pointerenter can't drive this — native pointerenter does not refire
  // when the pointer moves between children of the same ancestor.
  return (
    <div className="qsb" style={rootVars}>
      <div
        className="qsbHud hud-outline"
        data-quest-status-bar-anchor=""
        style={{
          position: "fixed",
          left: 0,
          right: 0,
          bottom: 0,
          height: QUEST_STATUS_BAR_TOTAL_HEIGHT,
          zIndex: 40,
        }}
      >
        <QsbHudBar
          essence={essence}
          deck={deck}
          onViewDeck={onViewDeck}
          dreamcaller={dreamcaller}
          scale={scale}
        />
      </div>

      <QsbDreamsignStrip
        signs={dreamsigns}
        stageRef={stageRef}
        scale={scale}
        onOpenWindow={() => setSignWindow(true)}
      />
      {signWindow && (
        <QsbDreamsignWindow
          signs={dreamsigns}
          onClose={() => setSignWindow(false)}
        />
      )}
    </div>
  );
}
